{
  "source_poem_zh": "雨横风狂三月暮，\n门掩黄昏、无计留春住；\n泪眼问花花不语，\n乱红飞过秋千去。",
  "critical_units": [
    {
      "id": "song_09_u1",
      "source_span": "雨横风狂三月暮",
      "meaning": "以晚春风雨交加写季节将尽。"
    },
    {
      "id": "song_09_u2",
      "source_span": "无计留春住",
      "meaning": "把春光当作可以挽留却无法留住的对象。"
    },
    {
      "id": "song_09_u3",
      "source_span": "泪眼问花花不语",
      "meaning": "未明示身份的问者向花发问，花被写成沉默的回应者。"
    },
    {
      "id": "song_09_u4",
      "source_span": "乱红飞过秋千去",
      "meaning": "飞散的落花带走春日景象，也没有给出明确回答。"
    }
  ],
  "translations_to_score": [
    {
      "opaque_id": "x428addf7752bb4",
      "translation": "Rain slants, wild winds rage, as March draws to its close;\nThe door is shut at dusk—no way to keep spring here.\nWith tear-filled eyes I ask the flowers; they say nothing.\nScattered petals whirl past the swing and disappear.",
      "notes": []
    },
    {
      "opaque_id": "xa6a596026a52f7",
      "translation": "Rain lashes, the wild wind rages—spring wanes toward its end;\nAt dusk, the door is closed—there is no way to make spring remain.\nThrough tearful eyes I question the flowers; the flowers do not reply.\nA storm of crimson petals flies past the swing and away.",
      "notes": []
    },
    {
      "opaque_id": "xb9808f88d6d2bd",
      "translation": "The rain slants, the wind rages, at March’s end;\nThe door is shut at dusk—no way to keep spring here.\nWith tear-filled eyes, I ask the blossoms; they do not answer.\nA flurry of fallen petals flies past the swing and away.",
      "notes": []
    },
    {
      "opaque_id": "x916ed154a0231f",
      "translation": "Rain lashes, the wind rages, as the third month wanes;\nAt dusk I close the door—there is no way to make spring stay.\nThrough tearful eyes I ask the flowers; the flowers do not speak,\nAnd scattered blossoms fly past the swing and away.",
      "notes": [
        "The “third month” refers to the final month of spring in the traditional Chinese lunar calendar."
      ]
    },
    {
      "opaque_id": "x35296d9ed21af3",
      "translation": "Rain lashes sideways, wind runs wild; the third month wanes.\nThe door is shut against the dusk—no way to make spring stay.\nThrough tear-filled eyes I ask the flowers; the flowers say nothing.\nA flurry of red petals flies beyond the swing.",
      "notes": []
    },
    {
      "opaque_id": "xefca3172d70996",
      "translation": "Rain lashes, wind rages, as the third month wanes;\nAt dusk the door is shut—no way to keep spring here.\nThrough tearful eyes I ask the flowers; the flowers do not speak,\nWhile scattered reds fly past the swing and away.",
      "notes": []
    }
  ]
}

